        int centerN = (sx != 0) ? (h / 2) : (w / 2);
        int align = centerP - centerN;

        if (sx == -1) return new Vector2Int(px - w, align);              // 宸﹁竟
        if (sx == 1) return new Vector2Int(px + pw, align);             // 鍙宠竟
